function build(rows: Row[][], kind: 'EX' | 'RET'): AcademyQuestion[] {
  let number = 0, priorPosition = -1, positionRun = 0
  return rows.flatMap((chapter, chapterIndex) => chapter.map((row, localIndex) => {
    number++
    const marked = row.slice(1, 5).map((text) => ({ text: text.replace(/^\+/, ''), correct: text.startsWith('+') }))
    // Stable rotation avoids a key determined by the canonical writing order.
    let hash = 2166136261
    for (const character of row[0]) hash = Math.imul(hash ^ character.charCodeAt(0), 16777619)
    let shift = (hash >>> 0) % 4
    const isSingle = marked.filter((option) => option.correct).length === 1
    if (isSingle) {
      const correctIndex = marked.findIndex((option) => option.correct)
      let position = (correctIndex - shift + 4) % 4
      if (position === priorPosition && positionRun >= 3) { shift = (shift + 1) % 4; position = (position + 3) % 4 }
      positionRun = position === priorPosition ? positionRun + 1 : 1
      priorPosition = position
    }
    const options = [...marked.slice(shift), ...marked.slice(0, shift)].map((option, index) => ({ value: String.fromCharCode(65 + index), text: option.text, isCorrect: option.correct }))
    return { code: `WL002-${kind}-${kind === 'EX' ? 'E' : 'R'}${String(number).padStart(kind === 'EX' ? 2 : 3, '0')}`, version: 1,
      chapterNumber: chapterIndex + 1, type: options.filter((option) => option.isCorrect).length > 1 ? 'MULTI_CHOICE' : 'SINGLE_CHOICE',
      knowledgeAreas: [`WL002-H${chapterIndex + 1}-${areas[chapterIndex]}`], learningObjective: `Onderbouwd handelen bij ${areas[chapterIndex].toLocaleLowerCase('nl')}`,
      cognitiveLevel: kind === 'EX' ? (localIndex === 0 && chapterIndex < 8 ? 'B' : [1, 2].includes(localIndex) ? 'T' : 'A') : (localIndex < 2 ? 'B' : localIndex < 8 ? 'T' : 'A'),
      difficulty: localIndex < 2 ? 1 : localIndex < (kind === 'EX' ? 4 : 8) ? 2 : 3,
      criticalConcept: [0, 1, 4].includes(localIndex), legalReviewRequired: [0, 1, 4, 6, 7, 9].includes(chapterIndex),
      questionText: row[0], explanation: row[5], options, correctAnswer: options.filter((option) => option.isCorrect).map((option) => option.value), sourceIds: [sourceByChapter[chapterIndex]],
    } satisfies AcademyQuestion
  }))
}
export const wl002ExamQuestions = build(examRows, 'EX')
export const wl002RetentionQuestions = build(retentionRows, 'RET')
